head.script:
let isFilter = false;
let isSort = false;



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > insertData]<br/>지정한 Row 인덱스 위치에 1차원 배열로 Row 데이터를 한 건 이상 삽입합니다.",
    "validation" : [
        "rowIndex(필수) 파라미터로 Row 데이터가 삽입될 위치의 인덱스값을 숫자로 설정합니다.",
        "Row 의 인덱스는 0 부터 시작하며 필터링/정렬 설정에 맞게 인덱스를 설정합니다.",
        "data(필수) 파라미터로 삽입하려는 Row 데이터를 1차원 배열로 설정합니다.",
        "배열의 원소 갯수는 DataList 모듈에 정의된 Column 갯수의 배수와 일치해야 합니다.",
        "필터/정렬이 적용된 상태로 삽입된 데이터는 필터/정렬이 해제되면 마지막에 위치합니다.",
        "insertData() 메소드에 의해 Row 데이터가 삽입되면 oninsertrow 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // event 바인딩
    target1.bind("oninsertrow", function(e){ wf_body_bottom.getObj("scwin").setReturnValue("=====target1_oninsertrow=====");});

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true"', '', 'gridView1');

    isFilter = false;
    isSort = false;
}   



scwin.btn_setColumnFilter_onclick = function (e) {
    if (isFilter) {
        target1.clearFilter();  
        isFilter = false;  
    }
    else {
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_2", condition:'and'})
        target1.setColumnFilter( {type:'row', colIndex:'col1', key:"col1_4", condition:'or'})        
        isFilter = true;
    }	

    scwin.btn_getInsertedData_onclick();
};



scwin.btn_sort_onclick = function (e) {
    if (isSort) {    
        target1.clearSort();
        isSort = false;
    }
    else {
        target1.sort("col1", 1);
        isSort = true;
    }

    scwin.btn_getInsertedData_onclick();
};



scwin.btn_getInsertedData_onclick = function (e) {
    let rtn = target1.getInsertedData();  

    for (var i=0; i < rtn.length; i++) {        
        wf_body_bottom.getObj("scwin").setReturnValue(`row[${i}] insertedData: ${rtn[i]}`);
    }   

    rtn = target1.getInsertedIndex();

    for (var i=0; i < rtn.length; i++) {        
        wf_body_bottom.getObj("scwin").setReturnValue(`row[${i}] insertedIndex : ${rtn[i]}`);
    }   
};



scwin.btn_insertData_onclick = function (e) {
    let rowIndex = par_rowIndex.getText();
    let data = par_data.getText();

	target1.insertData(Number(rowIndex), eval('{' + data + '}'));    

    scwin.btn_getInsertedData_onclick();
};
